local _alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _decode(_s)
    _s = _s:gsub("[^" .. _alphabet .. "=]", "")
    return (_s:gsub(".", function(_c)
        if _c == "=" then return "" end
        local _p = _alphabet:find(_c, 1, true) - 1
        local _r = ""
        for _i = 6, 1, -1 do
            _r = _r .. (((_p % 2^_i - _p % 2^(_i-1)) > 0) and "1" or "0")
        end
        return _r
    end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(_x)
        if #_x ~= 8 then return "" end
        local _n = 0
        for _i = 1, 8 do
            _n = _n + (_x:sub(_i,_i) == "1" and 2^(8-_i) or 0)
        end
        return string.char(_n)
    end))
end

local _src = _decode(_b)

local _load = loadstring or load
assert(_load, "ArceusXLibrary: loadstring no está disponible en este executor.")

local _fn, _err = _load(_src, "ArceusXLibrary")
if not _fn then
    error("ArceusXLibrary: error al cargar: " .. tostring(_err))
end

return _fn()
